"""Portable review of three signage + three touch layouts in both brands."""
from pathlib import Path
import argparse, hashlib, json, shutil

ROOT=Path(__file__).resolve().parents[1]
PUBLIC=ROOT/'apps/web/public'
INDEX=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JLL · Signage & touch experiences</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f3f2;color:#171c20;font:16px/1.45 Arial,sans-serif}button{font:inherit;cursor:pointer}header{background:white;border-bottom:1px solid #cbd1d1;padding:24px 36px}.overline{font-size:12px;letter-spacing:.15em;text-transform:uppercase;color:#606a6e}h1{font-size:34px;letter-spacing:-.035em;margin:8px 0}header p{margin:0;color:#59666a}.toolbar{padding:22px 36px;display:flex;align-items:center;gap:18px;flex-wrap:wrap}.group{display:flex}.group button{background:white;border:1px solid #bbc5c5;padding:10px 18px}.group button+button{border-left:0}.group [aria-pressed=true]{background:#171c20;border-color:#171c20;color:white}main{padding:0 36px 40px}.directions{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.directions button{padding:16px 20px;background:white;border:1px solid #bbc5c5;text-align:left}.directions [aria-pressed=true]{border-top:4px solid #e30613;padding-top:13px}.directions strong{font-size:19px}.directions small{display:block;color:#586469;margin-top:5px}.actions{display:flex;align-items:center;gap:18px;margin:23px 0}.actions button{padding:12px 20px;background:white;border:1px solid #bbc5c5}.actions .primary{background:#e30613;border-color:#e30613;color:white;font-weight:bold}.hint{font-size:14px;color:#5e686c;margin-left:auto}.stage-area{max-width:1600px;margin:auto}.after-frame{display:block;width:100%;aspect-ratio:16/9;border:0;background:white}.portrait .after-frame{aspect-ratio:9/16;max-height:1400px;width:min(100%,787.5px);margin:auto}.compare{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.compare .after-frame{max-height:none;width:100%}.before{display:none}.compare .before{display:block}.before iframe{display:block;width:100%;aspect-ratio:16/9;border:0}.compare.portrait iframe{aspect-ratio:9/16}.caption{font-size:14px;margin:0 0 12px;color:#59666a}.caption strong{font-size:17px;color:#171c20}.notes{display:grid;grid-template-columns:1fr 1fr;gap:40px;border-top:1px solid #cbd1d1;margin-top:30px;padding-top:22px}.notes h2{font-size:19px;margin:0 0 8px}.notes p{font-size:14px;color:#536167;margin:0 0 12px}.notes a{color:#ab0710}.backdrop,.close-full{display:none}.full-preview .backdrop{display:block;position:fixed;top:0;left:0;width:100%;height:100%;background:#0a1012;z-index:100}.full-preview .after-frame{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:min(100vw,calc(100vh*16/9));height:min(100vh,calc(100vw*9/16));max-height:none;aspect-ratio:auto;z-index:101}.full-preview .portrait .after-frame{width:min(100vw,calc(100vh*9/16));height:min(100vh,calc(100vw*16/9));max-height:none}.full-preview .close-full{display:block;position:fixed;right:12px;top:12px;z-index:102;padding:10px 16px;background:white;border:1px solid #bcc6c7}.primary:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #2c75b9;outline-offset:3px}@media(max-width:900px){header{padding:22px}h1{font-size:28px}.toolbar{padding:20px}main{padding:0 20px 30px}.directions{grid-template-columns:1fr}.actions{flex-wrap:wrap}.hint{width:100%;margin:0}.notes,.compare{grid-template-columns:1fr}}
/* Review controls are separate from the full-screen property experience. */
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;background:#f6f6f4}header{padding:24px 36px 22px}h1{font-size:30px}.toolbar{gap:24px;padding:20px 36px}.group{background:#e9eae7;border-radius:12px;padding:4px;gap:4px}.group button,.group button+button{border:0;background:transparent;border-radius:9px;min-height:44px}.group [aria-pressed=true]{background:white;color:#171c20;box-shadow:0 1px 5px #171c2018}.directions button{border-radius:14px;border:1px solid #d8dcda;padding:16px 20px;transition:background .15s}.directions [aria-pressed=true]{background:#fff;border:2px solid #e30613;padding:15px 19px}.directions button:not([aria-pressed=true]){background:#efefec}.actions button{border-radius:10px;min-height:46px}.after-frame{border-radius:16px;box-shadow:0 12px 40px #17212514}.full-preview .after-frame{border-radius:0;box-shadow:none}.close-full{border-radius:10px}.caption{margin-bottom:14px}.notes{max-width:1600px;margin-left:auto;margin-right:auto}button:hover{filter:brightness(.97)}
</style></head><body><header><div class="overline">JLL + reusable collection · October 2026</div><h1>Explore the property. Your way.</h1><p>Three approved signage directions, now with photo carousels and optional video, plus three matching touch experiences.</p></header><div class="toolbar"><div class="group"><button data-family="touch" aria-pressed="true">Touch experiences</button><button data-family="signage" aria-pressed="false">Digital signage</button></div><div class="group"><button data-brand="jll" aria-pressed="true">JLL</button><button data-brand="generic" aria-pressed="false">Generic</button></div><div class="group"><button data-orientation="landscape" aria-pressed="true">Landscape</button><button data-orientation="portrait" aria-pressed="false">Portrait</button></div></div><main><nav class="directions" aria-label="Template directions"></nav><div class="actions"><button class="primary" data-full>Open full-screen experience ↗</button><button data-compare aria-pressed="false">Compare with first pass</button><button data-motion aria-pressed="true">Pause photo carousel</button><span class="hint">Use full screen for the best touch experience.</span></div><section class="stage-area"><article class="before"><p class="caption"><strong>Before · First pass</strong></p><iframe title="Original template" sandbox="allow-scripts"></iframe></article><article class="after"><p class="caption"><strong id="current-name">A · Guided property tour</strong> · Live, interactive preview</p><iframe class="after-frame" title="New property experience" sandbox="allow-scripts" allow="autoplay"></iframe></article></section><div class="notes"><section><h2>Designed for an actual property conversation.</h2><p>Large touch targets, three amenity stories, all eight published plan sheets, zoom and drag, a photo gallery, location, specifications and a QR handoff to the leasing team. The experience returns to its opening screen after two minutes of inactivity.</p><p>The three touch templates offer different entrances to the same full property story: guided, immersive or direct access. Both brands support landscape and portrait. Portrait navigation is centered on the display, with large controls grouped nearby.</p></section><section><h2>Your existing CMS controls.</h2><p>Replace images and plans, reorder carousel photos, change timing and transitions, upload an optional property video and poster, and edit every text field, theme, font and saved text position. A missing or failed video falls back to photography.</p><p>No property film has been supplied; the preview uses photo carousels. Video support has been checked with a playback fixture. These files are ready for review and have not been installed in a live customer tenant.</p><p>JLL source: <a href="https://property.jll.co.uk/listings/1-liverpool-street" target="_blank" rel="noopener">One Liverpool Street listing and floor plans</a>. Availability is a reviewed snapshot; generic property content is illustrative. <a href="README.md">Handoff notes</a>.</p></section></div></main><div class="backdrop"></div><button class="close-full" data-close>Close full screen</button><script>
const labels={touch:[['Guided property tour','A clear, broker-led property presentation.'],['Immersive property showcase','A cinematic invitation to explore.'],['Leasing information hub','Direct access to the details that matter.']],signage:[['Architectural','Clean type and a large architectural carousel.'],['Hospitality','Immersive property imagery and protected copy.'],['Editorial','An oversized title and bold brand color.']]};let family='touch',brand='jll',orientation=new URLSearchParams(location.search).get('orientation')==='portrait'?'portrait':'landscape',direction='a',motion=true,compare=false;
const after=document.querySelector('.after-frame'),before=document.querySelector('.before iframe'),area=document.querySelector('.stage-area');
function config(){return btoa(JSON.stringify({'carousel.autoplay':motion?'yes':'no'}));}
function afterURL(){return 'templates/custom/'+(family==='touch'?'jll-touch-experiences':'jll-overview-directions')+'/'+brand+'-'+direction+'.html?orientation='+orientation+'&text='+config();}
function render(){document.querySelectorAll('[data-family],[data-brand],[data-orientation]').forEach(b=>{const value=b.dataset.family||b.dataset.brand||b.dataset.orientation;b.setAttribute('aria-pressed',[family,brand,orientation].includes(value));});document.querySelector('.directions').innerHTML=labels[family].map((x,i)=>'<button data-direction="'+String.fromCharCode(97+i)+'" aria-pressed="'+(direction===String.fromCharCode(97+i))+'"><strong>'+String.fromCharCode(65+i)+' · '+x[0]+'</strong><small>'+x[1]+'</small></button>').join('');document.querySelector('#current-name').textContent=direction.toUpperCase()+' · '+labels[family][direction.charCodeAt(0)-97][0];area.classList.toggle('portrait',orientation==='portrait');area.classList.toggle('compare',compare);after.src=afterURL();if(compare)before.src='templates/'+(brand==='jll'?'custom/jll-commercial-real-estate':family==='touch'?'kiosk/commercial-real-estate':'signage/corporate/commercial-real-estate')+'/'+(family==='touch'?'07-guided-property-tour':'01-property-overview')+'.html?orientation='+orientation+'&text='+btoa(JSON.stringify({'carousel.autoplay':'no'}));else before.removeAttribute('src');}
function close(){document.body.classList.remove('full-preview');document.querySelector('[data-full]').focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;for(const key of ['family','brand','orientation','direction'])if(b.dataset[key]){if(key==='family')family=b.dataset[key];if(key==='brand')brand=b.dataset[key];if(key==='orientation')orientation=b.dataset[key];if(key==='direction')direction=b.dataset[key];render();}if(b.hasAttribute('data-compare')){compare=!compare;b.setAttribute('aria-pressed',compare);b.textContent=compare?'Show new design only':'Compare with first pass';render();}if(b.hasAttribute('data-motion')){motion=!motion;b.setAttribute('aria-pressed',motion);b.textContent=motion?'Pause photo carousel':'Play photo carousel';after.contentWindow.postMessage({type:'educms-overrides',text:{'carousel.autoplay':motion?'yes':'no'}},'*');}if(b.hasAttribute('data-full')){document.body.classList.add('full-preview');document.querySelector('[data-close]').focus();}if(b.hasAttribute('data-close'))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});render();
</script></body></html>'''

def package(out):
    out.mkdir(parents=True,exist_ok=True)
    for folder in ['custom/jll-overview-directions','custom/jll-touch-experiences','custom/jll-commercial-real-estate','signage/corporate/commercial-real-estate','kiosk/commercial-real-estate']:
        src=PUBLIC/'templates'/folder;dest=out/'templates'/folder
        dest.mkdir(parents=True,exist_ok=True)
        if folder.endswith(('directions','experiences')):shutil.copytree(src,dest,dirs_exist_ok=True)
        else:
            for filename in ['01-property-overview.html','07-guided-property-tour.html']:
                if (src/filename).exists():shutil.copy2(src/filename,dest/filename)
            if (src/'_assets').exists():shutil.copytree(src/'_assets',dest/'_assets',dirs_exist_ok=True)
    shutil.copy2(PUBLIC/'templates/_native-image-carousel.js',out/'templates/_native-image-carousel.js')
    (out/'index.html').write_text(INDEX)
    rows=[]
    for family,folder in [('signage','jll-overview-directions'),('touch','jll-touch-experiences')]:
        for brand in ['jll','generic']:
            for variant in ['a','b','c']:
                for orientation in ['landscape','portrait']:
                    url='/templates/custom/'+folder+'/'+brand+'-'+variant+'.html'+('?orientation=portrait' if orientation=='portrait' else '')
                    rows.append({'id':brand+'-property-'+family+'-'+variant+('-portrait' if orientation=='portrait' else ''),'collection':'jll' if brand=='jll' else 'standard','family':family,'orientation':orientation.upper(),'isTouchEnabled':family=='touch','idleResetMs':120000 if family=='touch' else 0,'url':url,'screenWidth':2160 if orientation=='portrait' else 3840,'screenHeight':3840 if orientation=='portrait' else 2160,'sha256':hashlib.sha256((PUBLIC/url.split('?')[0].lstrip('/')).read_bytes()).hexdigest(),'zone':{'widgetType':'EXTERNAL_HTML','x':0,'y':0,'width':100,'height':100,'defaultConfig':{'url':url}}})
    (out/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
    (ROOT/'docs/templates/jll-property-experiences-review-manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
    notes='''# JLL signage and touch experiences

User approved all three overview directions on October 4, 2026, then requested image carousels, optional video and matching touch experiences.

## Contents

- Three signage layouts: Architectural, Hospitality, Editorial.
- Three touch layouts: Guided property tour, Immersive property showcase, Leasing information hub.
- Each has a JLL and generic version, each supporting landscape and portrait: 12 HTML templates / 24 formats.
- Seven touch pages: overview, amenities, plans, location, details, contact, gallery. Three amenity selections and eight floor-plan sheets, covering all published levels for the JLL example. Every section is one tap away in an icon-and-label navigation dock. All eight floor buttons stay visible, and Back preserves the selected floor and zoom. The gallery has manual previous/next and direct image selection. Photo hero carousels autoplay by default.

## Portrait touch composition

The portrait layout has its own composition. Section navigation and Back sit around the vertical center (43–55% of display height), with page-specific controls nearby. Visible button centers remain within 35–70% of the screen height; no primary navigation sits at the bottom edge. Home resets the portrait experience, replacing duplicate top-edge reset buttons. The actual physical reach still depends on display size and mounting height.

Architecture, immersive imagery and the information hub retain distinct portrait entrances. A uses a large photo above the controls and property information below; B uses an immersive upper hero and a lower workplace photograph; C uses a split heading/photograph above the controls. The extra portrait photo is an ordinary editable native image slot.

## Existing CMS tool compatibility

Native image galleries: replace/reorder photos through the Image picker or `media.<slot>.slides`; configure `carousel.intervalSeconds`, autoplay and transition, plus per-slot fit/crop/mode. Defaults rotate every seven seconds.

Video: the existing Video picker discovers `property.film`. Supply a browser-playable MP4/WebM and optionally replace `property.film.poster` using the image picker. Video is silent, inline and looping by default. The `video.autoplay`, `video.loop`, `media.property.film.fit` and `media.property.film.position` fields remain editable. Missing, blocked or failed video leaves photography visible. Videos pause on hidden touch pages. No real property film is bundled; the automated playback fixture is excluded from this deliverable.

All visible copy exposes data-field and the V14 click-to-edit shim. Colors, fonts and scale use existing theme fields. Text styles and saved positions use the native layout adapter. Plans use contained image slots. QR is generated from the editable `contact.url` and accepts only HTTP/HTTPS. `tour.startPage` controls the initial page; `tour.idleSeconds` defaults to 120 and resets navigation, floors, gallery and zoom. The suggested template idleResetMs is 120000 for touch records.

## Content provenance

JLL photos/renderings, published plans and property facts: https://property.jll.co.uk/listings/1-liverpool-street (reviewed October 3–4, 2026). Watermarks are intact. Floor plates are presented as published plans, without implying all floors are available. Available space is a reviewed snapshot; confirm live leasing facts with JLL.

Generic branding, property details and concept plans are illustrative. Its stock photography is independent of JLL, from the existing licensed/reference asset collection and https://images.unsplash.com/photo-1486406146926-c627a92ad1ab. The font and QR dependency licenses remain in the shared assets directory.

## Delivery state

Local, reviewable EXTERNAL_HTML templates. No live tenant, database, deployment or device was changed. The 24-format review manifest includes source hashes, zone config, orientations and touch flags. It is separate from the earlier 32-record collection installer; do not pass it to that installer. JLL versions must remain customer-scoped. Generic versions can be registered as Corporate / Touch Kiosk presets after touch design review.

The rest of the original collection remains in the first review. This update covers the three approved overview directions and three new matching touch experiences.

## Verification

See verification for actual Chromium/WebKit captures and results. Checks include information text sizes, overlaps, 720p touch targets, direct navigation, Back history, amenity/floor/gallery selection, plan zoom and drag, idle reset, QR validation, hidden-page CMS editing, saved text positions, edit/preview transitions, carousel playback, MP4 playback and photo fallback. Final physical display sizing still depends on screen dimensions and viewing distance.

Run Launch Preview.command or serve this folder on localhost port 8929. Open full-screen preview retains the active touch page.
'''
    (out/'README.md').write_text(notes)
    (ROOT/'docs/templates/jll-property-experiences-review.md').write_text(notes)
    (out/'serve.py').write_text('from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer\nfrom pathlib import Path\nimport os\nos.chdir(Path(__file__).resolve().parent)\nclass Handler(SimpleHTTPRequestHandler):\n    def log_message(self, *args): pass\nclass Server(ThreadingHTTPServer):\n    request_queue_size = 128\nServer(("127.0.0.1", 8929), Handler).serve_forever()\n')
    launcher=out/'Launch Preview.command';launcher.write_text('#!/bin/zsh\ncd -- "${0:A:h}"\nopen "http://127.0.0.1:8929/index.html"\npython3 serve.py\n');launcher.chmod(0o755)
    print(json.dumps({'output':str(out),'formats':len(rows)}))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);package(p.parse_args().output.expanduser().resolve())
